<?php

declare(strict_types=1);

use App\MasterData\MasterDataException;
require_once __DIR__ . '/_guard.php';
require_once __DIR__ . '/_master_ui.php';
$service=master_data_service();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);if($action==='save'){$service->savePengurus($_POST,$id?:null);master_flash('success','Data pengurus berhasil disimpan. Pengurus tidak dibuatkan akun login.');}else{$service->setPengurusState($id,$action);master_flash('success','Status pengurus berhasil diperbarui.');}}catch(MasterDataException $e){master_flash('danger',$e->getMessage());}master_redirect('admin_pengurus.php');}
$page=max(1,(int)($_GET['page']??1));$filters=['q'=>$_GET['q']??'','state'=>$_GET['state']??'active'];$result=$service->pengurusList($filters,$page);$selected=isset($_GET['id'])?$service->pengurus((int)$_GET['id']):null;$mode=(string)($_GET['action']??'');master_header('Master Data Pengurus', ['show_heading' => false]);
?>
<div class="d-flex justify-content-between border-bottom pb-3 mb-4"><div><h1 class="h3">Master Data Pengurus</h1><p class="text-muted mb-0">Pengurus tidak memperoleh akun login pada V1.</p></div><a class="btn btn-success align-self-center" href="?action=create">Tambah Pengurus</a></div>
