<?php if($mode==='detail'&&$selected): ?><div class="card border-0 shadow-sm mb-4"><div class="card-header bg-white d-flex justify-content-between"><strong>Detail Pengurus #<?= (int)$selected['id'] ?></strong><a href="?action=edit&amp;id=<?= (int)$selected['id'] ?>">Ubah</a></div><div class="card-body row g-3"><div class="col-md-4"><small class="text-muted d-block">Nama</small><?= master_e($selected['nama']) ?></div><div class="col-md-3"><small class="text-muted d-block">Identitas</small><?= master_e($selected['nomor_identitas']?:'-') ?></div><div class="col-md-2"><small class="text-muted d-block">Nomor HP</small><?= master_e($selected['no_hp']?:'-') ?></div><div class="col-md-3"><small class="text-muted d-block">Jabatan</small><?= master_e($selected['jabatan']) ?></div></div></div><?php endif; ?>
<form method="get" class="card card-body border-0 shadow-sm mb-3"><div class="row g-2"><div class="col-md-6"><input class="form-control" name="q" value="<?= master_e($filters['q']) ?>" placeholder="Cari nama, identitas, jabatan, atau HP"></div><div class="col-md-3"><select class="form-select" name="state"><?php foreach(['active'=>'Aktif','inactive'=>'Nonaktif','archived'=>'Arsip','all'=>'Semua'] as $v=>$l): ?><option value="<?= $v ?>" <?= $filters['state']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary">Terapkan</button></div></div></form>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>ID</th><th>Nama</th><th>Identitas</th><th>HP</th><th>Jabatan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($result['rows'] as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= master_e($r['nama']) ?></td><td><?= master_e($r['nomor_identitas']?:'-') ?></td><td><?= master_e($r['no_hp']?:'-') ?></td><td><?= master_e($r['jabatan']) ?></td><td><?= $r['archived_at']?'Arsip':((int)$r['is_active']===1?'Aktif':'Nonaktif') ?></td><td><div class="d-flex gap-1"><a class="btn btn-sm btn-outline-primary" href="?action=detail&amp;id=<?= (int)$r['id'] ?>">Detail</a><a class="btn btn-sm btn-outline-warning" href="?action=edit&amp;id=<?= (int)$r['id'] ?>">Ubah</a><form method="post"><?= master_csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-secondary" name="action" value="<?= (int)$r['is_active']===1?'deactivate':'activate' ?>"><?= (int)$r['is_active']===1?'Nonaktifkan':'Aktifkan' ?></button></form><form method="post"><?= master_csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger" name="action" value="<?= $r['archived_at']?'restore':'archive' ?>"><?= $r['archived_at']?'Pulihkan':'Arsipkan' ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php master_pagination((int)$result['total'],$page,20);master_footer(); ?>
